import type { TranscriptNode } from "../types/transcript.js";
import type { ByteRange } from "../types/identity.js";
import type { CheckContext, Report } from "./context.js";
import { reporter } from "./context.js";
import type { Candidate } from "./candidate.js";
import { checkRevertApplication } from "./checks-revert.js";
import {
  canonicalApplicationBytes, complement, digest, equal, join, length, sameRanges, validRange,
} from "./bytes.js";
import { checkRecall } from "./recall.js";
import type { Replacement } from "./types.js";

function partition(ranges: readonly ByteRange[], size: number): boolean {
  let cursor = 0;
  for (const range of [...ranges].sort((a, b) => a.startByte - b.startByte)) {
    if (!validRange(range, size) || range.startByte !== cursor) return false;
    cursor = range.endByteExclusive;
  }
  return cursor === size;
}
function checkReplacement(c: CheckContext, r: Replacement, expected: Uint8Array | undefined, report: Report): void {
  const node = c.nodes.get(r.source.nodeId);
  if (node === undefined) { report("unknown-source", "Rendered replacement names an unknown source", r.source.nodeId); return; }
  if (r.source.sha256 !== node.sha256) report("source-hash-mismatch", "Rendered source hash changed", node.id);
  if (r.source.byteLength !== node.bytes.length) report("source-length-mismatch", "Rendered source length changed", node.id);
  const declared = c.value.plans.flatMap(p => p.removals.flatMap(rem => rem.sources
    .filter(s => s.source.nodeId === node.id).flatMap(s => s.ranges))).sort((a, b) => a.startByte - b.startByte);
  const copies = r.retainedCopies, sourceRanges = copies.map(copy => copy.sourceRange);
  const generatedLength = r.generatedRanges.reduce((sum, range) => sum + length(range), 0);
  const copiedLength = copies.reduce((sum, copy) => sum + length(copy.outputRange), 0);
  const declaredLength = declared.reduce((sum, range) => sum + length(range), 0);
  if (!partition([...copies.map(copy => copy.outputRange), ...r.generatedRanges], r.bytes.length)
    || copiedLength + generatedLength !== r.bytes.length
    || node.bytes.length - (r.bytes.length - generatedLength) !== declaredLength) {
    report("unaccounted-removal", "Final output length minus generated bytes disagrees with declared removals", node.id);
  }
  try {
    const missing = complement(sourceRanges, node.bytes.length);
    if (!sameRanges(missing, declared)) report("unaccounted-removal", "Retained source coverage differs from declared removal ranges", node.id);
    if (declared.some(d => !missing.some(m => m.startByte <= d.startByte && m.endByteExclusive >= d.endByteExclusive))) {
      report("unused-removal", "Declared removed bytes are retained in final output", node.id);
    }
  } catch { report("retained-bytes-changed", "Retained source ranges overlap, move backward or escape source bounds", node.id); }
  let previousOutputEnd = 0;
  for (const copy of copies) {
    if (!validRange(copy.sourceRange, node.bytes.length) || !validRange(copy.outputRange, r.bytes.length)
      || copy.outputRange.startByte < previousOutputEnd
      || length(copy.sourceRange) !== length(copy.outputRange)
      || !equal(node.bytes.slice(copy.sourceRange.startByte, copy.sourceRange.endByteExclusive),
        r.bytes.slice(copy.outputRange.startByte, copy.outputRange.endByteExclusive))) {
      report("retained-bytes-changed", "Copied output bytes differ from the authoritative source slice or order", node.id);
    }
    previousOutputEnd = copy.outputRange.endByteExclusive;
  }
  if (digest(r.bytes) !== r.sha256) report("retained-bytes-changed", "Replacement hash differs from final output bytes", node.id);
  if (expected === undefined || r.generatedRanges.some(range => !validRange(range, r.bytes.length))
    || !equal(join(r.generatedRanges.map(range => r.bytes.slice(range.startByte, range.endByteExclusive))), expected)) {
    report("invalid-generated-record", "Generated replacement bytes differ from the trusted template", node.id);
  }
  const cap = c.value.plans.flatMap(p => p.operations.map(op => ({ p, op }))).find(({ p, op }) =>
    op.kind === "cap" && p.removals.find(rem => rem.id === op.removalId)?.sources.some(s => s.source.nodeId === node.id));
  if (cap?.op.kind === "cap") {
    const head = cap.op.keepHeadEndByte;
    const expectedCopies = head === 0 ? [] : [{ startByte: 0, endByteExclusive: head }];
    if (!sameRanges(sourceRanges, expectedCopies) || !sameRanges(copies.map(copy => copy.outputRange), expectedCopies)
      || r.generatedRanges.length !== 1 || r.generatedRanges[0]?.startByte !== head
      || r.generatedRanges[0]?.endByteExclusive !== r.bytes.length) {
      report("invalid-generated-record", "Cap output must contain its exact head followed by one complete marker", node.id);
    }
  }
}

export function checkOutputTopology(c: CheckContext, output: readonly TranscriptNode[]): void {
  const report = reporter(c, null, null);
  const before = [...c.value.snapshot.nodes];
  if (c.value.input.kind === "entry") before.push(c.value.input.result);
  if (before.length !== output.length || before.some((node, i) => node.id !== output[i]?.id)) {
    report("adjacency-changed", "Application changed node count, order or neighboring node identities");
  }
  const calls = new Map<string, number>(), results = new Set<string>();
  output.forEach((node, index) => {
    const original = before[index];
    if (original === undefined || original.kind !== node.kind || original.id !== node.id
      || original.turnOrdinal !== node.turnOrdinal || original.stepOrdinal !== node.stepOrdinal) {
      report("adjacency-changed", "Application changed a transcript envelope", node.id); return;
    }
    if (original.kind === "message" && node.kind === "message") {
      if (original.role !== node.role || !equal(original.bytes, node.bytes)) {
        report("retained-bytes-changed", "System, developer, user and assistant messages must remain byte-identical", node.id);
      }
      if (!equal(canonicalApplicationBytes(original.toolCallIds), canonicalApplicationBytes(node.toolCallIds))) {
        report("pairing-changed", "Application changed assistant call IDs", node.id);
      }
      for (const id of node.toolCallIds) {
        if (calls.has(id)) report("pairing-changed", "Duplicate output call ID", node.id);
        calls.set(id, index);
      }
    }
    if (original.kind === "tool-result" && node.kind === "tool-result") {
      const callIndex = calls.get(node.callId);
      if (original.callId !== node.callId || callIndex === undefined || callIndex >= index || results.has(node.callId)) {
        report("pairing-changed", "Result no longer uniquely follows its original tool call", node.id);
      }
      results.add(node.callId);
    }
    const mentioned = c.value.plans.some(p => p.removals.some(r => r.sources.some(s => s.source.nodeId === node.id)));
    if (!mentioned && !equal(original.bytes, node.bytes)) {
      report("retained-bytes-changed", "Unmentioned node bytes changed", node.id);
    }
  });
}

export function checkOutput(c: CheckContext, candidate: Candidate): void {
  const report = reporter(c, null, null), seen = new Set<string>();
  for (const replacement of candidate.replacements) {
    if (seen.has(replacement.source.nodeId)) report("conflicting-operations", "Multiple replacements for one source", replacement.source.nodeId);
    seen.add(replacement.source.nodeId);
    checkReplacement(c, replacement, candidate.expectedGenerated.get(replacement.source.nodeId), report);
  }
  // A verdict removal is applied by checkpoint-revert: its bytes leave the
  // transcript and the appended receipt takes their place, so it has no
  // in-place replacement to demand (design-protocol §3, §5 Slice 3).
  const reverted = new Set(c.value.plans.flatMap(plan => plan.operations.flatMap(op =>
    op.kind === "verdict" ? [op.removalId] : [])));
  for (const plan of c.value.plans) for (const removal of plan.removals) {
    if (reverted.has(removal.id)) continue;
    for (const source of removal.sources) if (!seen.has(source.source.nodeId)) {
      report("unused-removal", "Declared removal has no final replacement", source.source.nodeId);
    }
  }
  for (const plan of c.value.plans) for (const removal of plan.removals) {
    const archive = candidate.archives.find(a => a.ruleId === plan.ruleId && a.removalId === removal.id);
    if (archive === undefined) report("recall-manifest-mismatch", "Declared removal has no complete archive");
    else {
      checkRecall(archive.recall, c.value.snapshot.sessionId, report);
      if (archive.recall.parts.length !== removal.sources.length || removal.sources.some(source => {
        const part = archive.recall.parts.find(p => p.source.nodeId === source.source.nodeId);
        const node = c.nodes.get(source.source.nodeId);
        return part === undefined || node === undefined || !equal(part.bytes, node.bytes)
          || !equal(canonicalApplicationBytes(part.source), canonicalApplicationBytes(source.source))
          || !sameRanges(part.removedRanges.map(s => s.range), source.ranges);
      })) report("recall-manifest-mismatch", "Archive does not cover precisely the declared source bodies and ranges");
      for (const source of removal.sources) {
        const replacement = candidate.replacements.find(r => r.source.nodeId === source.source.nodeId);
        if (reverted.has(removal.id)) {
          // A reverted unit's evidence is the receipt, never a rewritten body.
          if (replacement !== undefined) {
            report("conflicting-operations", "A verdict removal cannot also rewrite its source in place",
              source.source.nodeId);
          }
        } else if (replacement?.evidenceRecallId !== archive.recall.id) {
          report("recall-manifest-mismatch", "Replacement evidence recall ID differs from its archive");
        }
      }
    }
  }
  const recordIds = new Set<string>();
  for (const record of candidate.appendRecords) {
    const expected = candidate.expectedRecords.get(record.recordId);
    if (recordIds.has(record.recordId) || expected === undefined || !equal(record.bytes, expected)
      || digest(record.bytes) !== record.sha256) report("invalid-generated-record", "Appended record identity, bytes or hash differs from template");
    recordIds.add(record.recordId);
  }
  if (recordIds.size !== candidate.expectedRecords.size) report("invalid-generated-record", "Expected appended record is missing");
  const expectedSeals = c.value.plans.flatMap(p => p.operations.flatMap(op => op.kind === "seal" ? [op.episodeId] : []));
  if (!equal(canonicalApplicationBytes(expectedSeals), canonicalApplicationBytes(candidate.sealedEpisodeIds))) {
    report("invalid-generated-record", "Sealed episode IDs differ from validated seal operations");
  }
  // A revert moves the transcript, so the fixed-count topology audit cannot
  // speak for it: the plan's own claims are re-derived instead (§3, §5).
  if (reverted.size > 0 || candidate.revert !== null) {
    checkRevertApplication(c, candidate);
    return;
  }
  const before = [...c.value.snapshot.nodes];
  if (c.value.input.kind === "entry") before.push(c.value.input.result);
  const output = before.map(node => {
    const replacement = candidate.replacements.find(r => r.source.nodeId === node.id);
    return replacement === undefined ? node : { ...node, bytes: replacement.bytes, sha256: replacement.sha256,
      byteLength: replacement.bytes.length };
  });
  checkOutputTopology(c, output);
}
